let thumbnailEngine=null;const thumbnailCache=new Map();
function iconBurst(cv,type,palette,shell=null){
 const config=shell?structuredClone(shell):typeTune(defaultShell(type,palette));
 if(!shell){config.seed=(type+'|'+palette).split('').reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,7);delete config.id}
 // Cache by the complete design, so any visual edit creates a new image.
 const key=JSON.stringify(config);let picture=thumbnailCache.get(key);
 if(!picture){
  if(!thumbnailEngine){let surface=document.createElement('canvas');surface.getContext('2d',{alpha:true});thumbnailEngine=new FireworkEngine(surface);Object.assign(thumbnailEngine,{quality:'high',ground:false,stars:false,haze:0,wind:0,cameraShake:0});thumbnailEngine.sound.setEnabled(false);thumbnailEngine.background=()=>{};thumbnailEngine.resize(256,256,1)}
  const sim=thumbnailEngine;sim.reset(config.seed||1);sim.ctx.setTransform(1,0,0,1,0,0);sim.ctx.clearRect(0,0,256,256);
  const ground=['fountain','mine'].includes(config.type);
  if(config.type==='comet-fan'){config.launchWobble=0;sim.launch(config,.5)}else sim.burst(config,128,128,0,ground?-25:0,ground);
  const delay=config.layered?Math.max(0,...(config.layers||[]).filter(l=>l.enabled!==false).map(l=>+l.delay||0)):0,sample=clamp((+config.lifetime||3.2)*.35+delay*.5,.3,2.8);
  for(let time=0;time<sample;time+=1/30)sim.update(Math.min(1/30,sample-time));
  // Fit the actual particle and trail snapshot without changing the saved shell.
  let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;const include=(x,y)=>{minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x);maxY=Math.max(maxY,y)};
  for(const item of [...sim.particles,...sim.rockets]){include(item.x,item.y);for(const p of item.trail||[])include(p[0],p[1])}
  if(Number.isFinite(minX)){const scale=220/Math.max(40,maxX-minX,maxY-minY),dx=128-(minX+maxX)*scale/2,dy=128-(minY+maxY)*scale/2;for(const item of [...sim.particles,...sim.rockets,...sim.smokes,...sim.flashes]){item.x=item.x*scale+dx;item.y=item.y*scale+dy;if(item.px!=null)item.px=item.px*scale+dx;if(item.py!=null)item.py=item.py*scale+dy;if(item.size!=null)item.size*=scale;if(item.r!=null)item.r*=scale;for(const p of item.trail||[]){p[0]=p[0]*scale+dx;p[1]=p[1]*scale+dy}}}
  sim.render();picture=document.createElement('canvas');picture.width=picture.height=116;picture.getContext('2d').drawImage(sim.canvas,0,0,116,116);thumbnailCache.set(key,picture);if(thumbnailCache.size>160)thumbnailCache.delete(thumbnailCache.keys().next().value);
 }
 cv.width=cv.height=116;cv.getContext('2d').drawImage(picture,0,0);
}
