Q('#timelineScroll').ondrop=e=>{e.preventDefault();Q('.timeline-panel').classList.remove('timeline-drop-active');let raw=e.dataTransfer.getData('application/x-shamon-shell');if(!raw)return;commit('SHELL DROPPED ON TIMELINE');let shell=resolveDraggedShell(JSON.parse(raw)),track=+(e.target.closest('[data-track]')?.dataset.track??inferLane(shell));if(!shell||track===3)return;let marker=createCue(markerAtPoint(e),shell.id,lanesCollapsed?inferLane(shell):track);state.selectedShellId=shell.id;state.selectedEventId=markerEvents(marker.id).at(-1)?.id||null;renderAll();toast(`Added to detonation cue ${formatCueTime(marker.time)}`)};
Q('#timelineScroll').onmousedown=e=>{let markerEl=e.target.closest('[data-marker]');if(markerEl){let marker=markerById(markerEl.dataset.marker);if(!marker)return;e.preventDefault();state.selectedMarkerId=marker.id;QA('.cue-marker').forEach(x=>x.classList.toggle('selected',x===markerEl));cueDrag={marker,startX:e.clientX,startScroll:Q('#timelineScroll').scrollLeft,startTime:marker.time,moved:false};renderInspector();return}let p=timelinePoint(e);if(p.y<28)seek((p.x-118)/pixelsPerSecond())};
Q('#timelineScroll').ondblclick=e=>{let marker=e.target.closest('[data-marker]');if(marker){e.preventDefault();openMarkerManager(marker.dataset.marker)}};
window.addEventListener('mousemove',e=>{if(cueDrag){let distance=e.clientX-cueDrag.startX+Q('#timelineScroll').scrollLeft-cueDrag.startScroll;if(!cueDrag.moved&&Math.abs(distance)<2)return;if(!cueDrag.moved){commit('MARKER MOVED');cueDrag.moved=true}updateMarkerTime(cueDrag.marker,cueDrag.startTime+distance/pixelsPerSecond());renderTimeline();if(openMarkerId===cueDrag.marker.id)refreshMarkerManager()}});
window.addEventListener('mouseup',()=>{if(cueDrag){if(cueDrag.moved){autosave();status('DETONATION CUE MOVED')}cueDrag=null}});

function openMarkerManager(id){ensureMarkers();let marker=markerById(id);if(!marker)return;openMarkerId=id;state.selectedMarkerId=id;let panel=Q('#markerManager');panel.hidden=false;panel.style.zIndex=String(++popoutZ);refreshMarkerManager();renderTimeline()}
function refreshMarkerManager(){let marker=markerById(openMarkerId);if(!marker){Q('#markerManager').hidden=true;openMarkerId=null;return}let events=markerEvents(marker.id);Q('#markerTime').value=formatCueTime(marker.time);Q('#markerWindowSub').textContent=`DETONATION MOMENT · ${formatCueTime(marker.time)}`;Q('#markerSummary').textContent=`${events.length} firework${events.length===1?'':'s'} detonating at this exact moment · launch times are calculated automatically`;Q('#cueList').innerHTML=events.length?events.map(e=>{let shell=state.shells.find(s=>s.id===e.shellId);return`<div class="cue-row" data-cue-event="${e.id}"><canvas data-cue-thumb data-type="${shell?.type||'chrysanthemum'}" data-palette="${shell?.palette||'Imperial Gold'}"></canvas><div class="cue-identity"><b>${esc(shell?.name||'Missing shell')}</b><small>Detonates at ${formatCueTime(marker.time)}</small></div><label class="cue-control"><span>HEIGHT LANE</span><select data-cue-field="track"><option value="0" ${e.track===0?'selected':''}>High Aerial</option><option value="1" ${e.track===1?'selected':''}>Low / Mid</option><option value="2" ${e.track===2?'selected':''}>Ground</option></select></label><label class="cue-control"><span class="position-scale"><i>◀ LEFT</i><b>HORIZONTAL POSITION</b><i>RIGHT ▶</i></span><input data-cue-field="x" type="range" min=".03" max=".97" step=".01" value="${e.x}" title="Move the firework left or right"></label><div class="row-actions"><button data-cue-action="edit">EDIT</button><button data-cue-action="duplicate">DUP</button><button class="danger" data-cue-action="delete">DEL</button></div></div>`}).join(''):'<div class="cue-empty">This marker is empty. Add a shell or drag one onto this exact detonation moment.</div>';QA('[data-cue-thumb]').forEach((c,i)=>iconBurst(c,c.dataset.type,c.dataset.palette,state.shells.find(s=>s.id===events[i].shellId)))}
Q('#markerTime').onchange=e=>{let marker=markerById(openMarkerId);if(!marker)return;commit('DETONATION TIME CHANGED');updateMarkerTime(marker,parseCueTime(e.target.value));renderTimeline();refreshMarkerManager();autosave()};
Q('#cueList').oninput=e=>{let row=e.target.closest('[data-cue-event]'),event=state.events.find(x=>x.id===row?.dataset.cueEvent),field=e.target.dataset.cueField;if(!event||!field)return;event[field]=field==='track'?Math.round(+e.target.value):+e.target.value;renderTimeline();autosave()};
Q('#cueList').onclick=e=>{let button=e.target.closest('[data-cue-action]'),row=e.target.closest('[data-cue-event]');if(!button||!row)return;let event=state.events.find(x=>x.id===row.dataset.cueEvent);if(!event)return;if(button.dataset.cueAction==='edit')openShellLab(event.shellId,event.id);if(button.dataset.cueAction==='duplicate'){commit('MARKER FIREWORK DUPLICATED');let copy=structuredClone(event);copy.id=uid();copy.ensembleArranged=false;state.events.push(copy);refreshMarkerManager();renderAll()}if(button.dataset.cueAction==='delete'){commit('MARKER FIREWORK DELETED');state.events=state.events.filter(x=>x.id!==event.id);if(state.selectedEventId===event.id)state.selectedEventId=null;refreshMarkerManager();renderAll()}};
Q('#markerManager').onclick=e=>{let action=e.target.closest('[data-marker-action]')?.dataset.markerAction,marker=markerById(openMarkerId);if(!action||!marker)return;if(action==='add-selected')openMarkerShellChooser(marker.id);if(action==='duplicate-marker'){commit('MARKER DUPLICATED');let time=snapCueTime(marker.time+.1);while(state.markers.some(m=>Math.abs(m.time-time)<.051)&&time<state.show.duration)time=snapCueTime(time+.1);let copy={id:uid(),time};state.markers.push(copy);for(const event of markerEvents(marker.id)){let e2=structuredClone(event);e2.id=uid();e2.markerId=copy.id;e2.time=time;state.events.push(e2)}openMarkerManager(copy.id);renderAll()}if(action==='delete-marker'&&confirm(`Delete the marker at ${formatCueTime(marker.time)} and all ${markerEvents(marker.id).length} attached designs?`)){commit('MARKER DELETED');state.events=state.events.filter(e=>e.markerId!==marker.id);state.markers=state.markers.filter(m=>m.id!==marker.id);state.selectedMarkerId=null;Q('#markerManager').hidden=true;openMarkerId=null;renderAll()}};

const LAB_MATERIALS=[['pearl','Pearl stars'],['streamer','Long streamers'],['glitter','Glitter compound'],['ember','Heavy embers'],['strobe','Strobe stars'],['crackle','Crackle stars']];
const LAB_LAYER_MATERIALS=[['','Inherit master'],...LAB_MATERIALS];
const LAB_SHAPES=[['sphere','Spherical volume'],['disc','Compressed disc'],['dome','Upper dome'],['cone','Rising cone'],['hourglass','Hourglass'],['cylinder','Cylindrical wall']];
let labLayerIndex=0,labSoloLayerId=null;
function makeLabLayer(name,type,palette,overrides={}){return{id:uid(),name,enabled:true,type,palette,colors:[...(PALETTES[palette]||PALETTES['Imperial Gold'])],material:'',sizeScale:1,densityScale:1,speedScale:1,lifetimeScale:1,spreadScale:1,trailScale:1,trailWidthScale:1,rotation:0,delay:0,glitter:0,crackle:0,strobe:0,...overrides}}
function ensureAdvancedShell(shell){if(!shell)return shell;const defaults={burstShape:'sphere',shapeThickness:.65,radialBias:0,turbulence:.08,fadeCurve:1.15,trailTaper:1,glitterOnset:.18,strobeRate:30,material:'pearl',layered:false};for(const [key,value] of Object.entries(defaults))if(shell[key]==null)shell[key]=value;if(!Array.isArray(shell.layers)||!shell.layers.length)shell.layers=[makeLabLayer('Outer Crown',shell.type,shell.palette),makeLabLayer('Inner Pistil','ring',shell.palette,{sizeScale:.55,densityScale:.58,speedScale:.92,lifetimeScale:.78,spreadScale:.9,trailScale:.62,rotation:18,delay:.04}),makeLabLayer('Core Flash','chrysanthemum',shell.palette,{sizeScale:.28,densityScale:.42,speedScale:.8,lifetimeScale:.48,spreadScale:.72,trailScale:.25,delay:.08,glitter:.34})];shell.layers=shell.layers.slice(0,12).map((layer,index)=>({...makeLabLayer(layer.name||`Layer ${index+1}`,layer.type||shell.type,layer.palette||shell.palette),...layer,id:layer.id||uid(),colors:Array.isArray(layer.colors)&&layer.colors.length?layer.colors:[...(PALETTES[layer.palette||shell.palette]||shell.colors)]}));labLayerIndex=clamp(labLayerIndex,0,shell.layers.length-1);return shell}
function selectedLabLayer(){ensureAdvancedShell(labDraft);return labDraft?.layers?.[labLayerIndex]||null}
function labPreviewShell(){let shell=structuredClone(labDraft);ensureAdvancedShell(shell);if(labSoloLayerId){shell.layered=true;shell.layers=shell.layers.filter(layer=>layer.id===labSoloLayerId)}return shell}
function labRange(key,label,min,max,step,value,layer=false){return`<label class="field"><span>${label}<output>${Number(value).toFixed(step===1?0:2)}</output></span><input ${layer?'data-layer-field':'data-lab-field'}="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></label>`}
function labSelect(key,label,value,options,layer=false){if(layer&&key==='material')options=LAB_LAYER_MATERIALS;return`<label class="field"><span>${label}</span><select ${layer?'data-layer-field':'data-lab-field'}="${key}">${options.map(([id,name])=>`<option value="${id}" ${value===id?'selected':''}>${name}</option>`).join('')}</select></label>`}
function labPerformance(shell){let layers=shell.layered?shell.layers.filter(layer=>layer.enabled):[];if(!layers.length)layers=[{sizeScale:1,densityScale:1,delay:0,lifetimeScale:1}];let weight=layers.reduce((sum,layer)=>sum+(layer.sizeScale||1)*(layer.densityScale||1),0),particles=Math.round(325*shell.size*shell.density*weight),duration=Math.max(...layers.map(layer=>(layer.delay||0)+shell.lifetime*(layer.lifetimeScale||1))),cost=particles<900?'LIGHT':particles<1800?'BALANCED':particles<3000?'HEAVY':'AUTO-LIMITED';return{particles,duration,cost,layers:shell.layered?shell.layers.filter(layer=>layer.enabled).length:1}}
function renderAdvancedLab(){ensureAdvancedShell(labDraft);let layer=selectedLabLayer(),stats=labPerformance(labDraft),disabled=labDraft.layered?'':' disabled';return`<div class="lab-readouts"><span><b>${stats.layers}</b> ACTIVE LAYERS</span><span><b>≈ ${stats.particles}</b> PARTICLES</span><span><b>${stats.duration.toFixed(1)}s</b> EFFECT LIFE</span><span class="cost-${stats.cost.toLowerCase()}"><b>${stats.cost}</b> LOAD</span></div><div class="group"><h3>BURST DESIGN</h3><div class="group-body"><label class="toggle-row"><span>Use multiple layers</span><input data-lab-field="layered" type="checkbox" ${labDraft.layered?'checked':''}></label>${labSelect('burstShape','Burst profile',labDraft.burstShape,LAB_SHAPES)}${labSelect('material','Main star appearance',labDraft.material,LAB_MATERIALS)}${labRange('shapeThickness','Burst thickness',.05,1,.01,labDraft.shapeThickness)}${labRange('radialBias','Inner / outer expansion',-1,1,.01,labDraft.radialBias)}${labRange('turbulence','Small movement variation',0,1,.01,labDraft.turbulence)}${labRange('fadeCurve','Brightness fade',.35,3,.01,labDraft.fadeCurve)}${labRange('trailTaper','Trail fade',.25,3,.01,labDraft.trailTaper)}${labRange('glitterOnset','Sparkle start time',0,.8,.01,labDraft.glitterOnset)}${labRange('strobeRate','Flash rate',8,60,1,labDraft.strobeRate)}</div></div><div class="group lab-layer-group${disabled}"><h3>SHELL LAYERS <span>${labSoloLayerId?'SOLO PREVIEW':''}</span></h3><div class="lab-layer-toolbar"><button data-layer-action="add" ${labDraft.layers.length>=12?'disabled':''} title="Add a layer, up to twelve">＋ ADD</button><button data-layer-action="duplicate" ${labDraft.layers.length>=12?'disabled':''} title="Duplicate this layer, up to twelve">DUPLICATE</button><button data-layer-action="up">↑</button><button data-layer-action="down">↓</button><button class="danger" data-layer-action="delete">DELETE</button></div><div class="lab-layer-list">${labDraft.layers.map((item,index)=>`<div class="lab-layer-row ${index===labLayerIndex?'selected':''} ${item.enabled?'':'off'}" data-layer-index="${index}"><button class="lab-layer-select" data-layer-index="${index}"><i style="background:${item.colors?.[0]||'#fff'}"></i><span><b>${esc(item.name)}</b><small>${esc(SHELLS.find(s=>s.id===item.type)?.name||item.type)} · ${item.delay.toFixed(2)}s</small></span></button><button class="lab-layer-solo ${labSoloLayerId===item.id?'active':''}" data-layer-action="solo" data-layer-index="${index}" title="Preview this layer alone" aria-label="Preview this layer alone">Solo</button></div>`).join('')}</div><div class="lab-layer-editor"><label class="toggle-row"><span>Layer enabled</span><input data-layer-field="enabled" type="checkbox" ${layer.enabled?'checked':''}></label><label class="field"><span>Layer name</span><input data-layer-field="name" type="text" value="${esc(layer.name)}"></label>${labSelect('type','Layer shape',layer.type,SHELLS.map(item=>[item.id,item.name]),true)}${labSelect('palette','Layer palette',layer.palette,Object.keys(PALETTES).map(name=>[name,name]),true)}${labSelect('material','Star appearance',layer.material,LAB_MATERIALS,true)}<div class="color-grid">${layer.colors.map((color,index)=>`<label>COLOR ${index+1}<input data-layer-color="${index}" type="color" value="${color}"></label>`).join('')}</div>${labRange('sizeScale','Size relative to main burst',.12,1.6,.01,layer.sizeScale,true)}${labRange('densityScale','Star count relative to main burst',.15,1.5,.01,layer.densityScale,true)}${labRange('speedScale','Expansion speed',.3,1.8,.01,layer.speedScale,true)}${labRange('lifetimeScale','Lifetime relative to main burst',.25,1.6,.01,layer.lifetimeScale,true)}${labRange('spreadScale','Spread scale',.25,1.6,.01,layer.spreadScale,true)}${labRange('trailScale','Trail length relative to main burst',0,1.5,.01,layer.trailScale,true)}${labRange('trailWidthScale','Trail width relative to main burst',.25,2,.01,layer.trailWidthScale,true)}${labRange('rotation','Layer rotation',-180,180,1,layer.rotation,true)}${labRange('delay','Start delay (s)',0,2,.01,layer.delay,true)}${labRange('glitter','Added glitter',0,1,.01,layer.glitter,true)}${labRange('crackle','Added crackle',0,1,.01,layer.crackle,true)}${labRange('strobe','Added strobe',0,1,.01,layer.strobe,true)}</div></div>`}

function openShellLab(shellId,eventId=null){let shell=state.shells.find(s=>s.id===shellId);if(!shell)return;if(labDraft&&labContext)labDrafts.set(labContext.shellId||"new",structuredClone(labDraft));labContext={shellId,eventId};labDraft=structuredClone(labDrafts.get(shellId)||shell);ensureAdvancedShell(labDraft);labLayerIndex=0;labSoloLayerId=null;let panel=Q('#shellLabWindow');panel.hidden=false;panel.style.zIndex=String(++popoutZ);Q('#labWindowSub').textContent=labDraft.name;renderLabLibrary();if(!labEngine){labEngine=new FireworkEngine(Q('#labCanvas'));Object.assign(labEngine,{ground:false,safe:false,backgroundStyle:'deep-night',stars:true,starIntensity:.8,haze:.18});labEngine.sound.setEnabled(state.show.sfxEnabled);labEngine.sound.setVolume(state.show.sfxVolume);labEngine.sound.setEffects(sfxEffects());labEngine.setQuality('high');labLoop(performance.now())}renderLabFields()}
function labLibraryEntries(){let claimed=new Set(),entries=libraryRecipes().map(recipe=>{let shell=state.shells.find(s=>!claimed.has(s.id)&&s.type===recipe.type&&s.palette===recipe.palette);if(shell)claimed.add(shell.id);return{...recipe,shell}});for(const shell of state.shells)if(!claimed.has(shell.id))entries.push({shell,...shell});for(const saved of state.userShells||[])if(!state.shells.some(s=>s.sourcePresetId===saved.presetId))entries.push({...saved,saved});if(labDrafts.has('new')||labContext&&!labContext.shellId)entries.unshift({...(labContext&&!labContext.shellId?labDraft:labDrafts.get('new')),draft:true});return entries}
let labLibraryItems=[];
function renderLabLibrary(){labLibraryItems=labLibraryEntries();Q('#labShellLibrary').innerHTML=labLibraryItems.map((entry,index)=>{let shell=entry.shell,draft=shell&&labDrafts.get(shell.id),name=draft?.name||shell?.name||entry.name,type=draft?.type||shell?.type||entry.type,palette=draft?.palette||shell?.palette||entry.palette,selected=entry.draft?!labContext?.shellId:shell?.id===labContext?.shellId;return`<button class="lab-shell-card ${selected?'selected':''}" data-lab-shell="${index}" title="${esc(name)}"><canvas data-type="${type}" data-palette="${palette}"></canvas><b>${esc(name.split(' · ')[0])}</b><span>${esc(palette)}</span></button>`}).join('');QA('#labShellLibrary canvas').forEach((c,i)=>{let entry=labLibraryItems[i],shell=entry.draft?labDrafts.get('new')||labDraft:entry.shell?labDrafts.get(entry.shell.id)||entry.shell:entry.saved;iconBurst(c,c.dataset.type,c.dataset.palette,shell)})}
Q('#labShellLibrary').onclick=e=>{let card=e.target.closest('[data-lab-shell]');if(!card)return;let entry=labLibraryItems[+card.dataset.labShell];if(!entry)return;if(entry.draft){slCancelPreview();if(labDraft&&labContext)labDrafts.set(labContext.shellId||'new',structuredClone(labDraft));labContext={shellId:null,eventId:null};labDraft=structuredClone(labDrafts.get('new')||entry);ensureAdvancedShell(labDraft);labLayerIndex=0;labSoloLayerId=null;Q('#labWindowSub').textContent=labDraft.name;renderLabFields();renderLabLibrary();slTime=0;slStartPreview();return}let shell=entry.shell;if(!shell){commit('SHELL OPENED IN LAB');shell=structuredClone(entry.saved||typeTune(defaultShell(entry.type,entry.palette)));shell.id=uid();shell.name=entry.name;if(entry.saved)shell.sourcePresetId=entry.saved.presetId;state.shells.push(shell);autosave();renderLibrary()}openShellLab(shell.id)};
function saveLabShell(){if(!labDraft||!labContext)return;commit('SHELL SAVED');let shell=state.shells.find(s=>s.id===labContext.shellId);if(shell){let id=shell.id,sourcePresetId=shell.sourcePresetId;Object.assign(shell,structuredClone(labDraft),{id,sourcePresetId})}else{shell=structuredClone(labDraft);shell.id=uid();state.shells.push(shell);labDrafts.delete('new')}labContext.shellId=shell.id;labDraft=structuredClone(shell);labDrafts.set(shell.id,structuredClone(shell));state.selectedShellId=shell.id;let preset=(state.userShells||[]).find(s=>s.presetId===shell.sourcePresetId);if(preset){let id=preset.id,presetId=preset.presetId,collection=preset.collection;Object.assign(preset,structuredClone(shell),{id,presetId,collection,savedAt:Date.now()})}Q('#labWindowSub').textContent=shell.name;autosave();renderAll();renderLabLibrary();if(openMarkerId)refreshMarkerManager();toast('Shell saved')}
function renderLabFields(){if(!labDraft)return;let tab=Q('.lab-tabs .active')?.dataset.labTab||'design';if(tab==='advanced'){Q('#labFields').innerHTML=renderAdvancedLab();return}Q('#labFields').innerHTML=GROUPS[tab].map(([title,fields])=>`<div class="group"><h3>${title}</h3><div class="group-body">${fields.map(f=>f[0]==='colors'?`<div class="color-grid">${labDraft.colors.map((x,i)=>`<label>COLOR ${i+1}<input data-lab-color="${i}" type="color" value="${x}"></label>`).join('')}</div>`:fieldHtml(f,labDraft,null).replaceAll('data-field','data-lab-field')).join('')}</div></div>`).join('')}
function labLoop(now){if(labEngine&&!Q('#shellLabWindow').hidden){labEngine.update(Math.min(.034,(now-(labEngine._lastLab||now))/1000));labEngine.render()}if(labEngine)labEngine._lastLab=now;labFrame=requestAnimationFrame(labLoop)}
Q('.lab-tabs').onclick=e=>{let tab=e.target.closest('[data-lab-tab]');if(!tab)return;QA('[data-lab-tab]').forEach(x=>x.classList.toggle('active',x===tab));renderLabFields()};
Q('#labFields').oninput=e=>{if(!labDraft)return;if(e.target.dataset.layerColor!=null){let layer=selectedLabLayer();if(layer)layer.colors[+e.target.dataset.layerColor]=e.target.value;return}if(e.target.dataset.layerField){let layer=selectedLabLayer(),key=e.target.dataset.layerField;if(!layer)return;let value=e.target.type==='checkbox'?e.target.checked:['range','number'].includes(e.target.type)?+e.target.value:e.target.value;layer[key]=value;if(key==='palette')layer.colors=[...PALETTES[value]];let out=e.target.previousElementSibling?.querySelector('output');if(out)out.textContent=Number(value).toFixed(e.target.step==='1'?0:2);if(['palette','type','material','enabled'].includes(key))renderLabFields();return}if(e.target.dataset.labColor!=null){labDraft.colors[+e.target.dataset.labColor]=e.target.value;return}let key=e.target.dataset.labField;if(!key)return;let value=e.target.type==='checkbox'?e.target.checked:['range','number'].includes(e.target.type)?+e.target.value:e.target.value;labDraft[key]=value;if(key==='palette'){labDraft.colors=[...PALETTES[value]];labDraft.name=`${SHELLS.find(x=>x.id===labDraft.type).name} · ${value}`;renderLabFields()}if(key==='type'){let definition=SHELLS.find(x=>x.id===value);typeTune(labDraft);labDraft.family=definition?.family||labDraft.family||'Custom';labDraft.name=`${definition.name} · ${labDraft.palette}`;renderLabFields()}if(['layered','breaks','colorMode'].includes(key))renderLabFields();let out=e.target.previousElementSibling?.querySelector('output');if(out)out.textContent=Number(value).toFixed(e.target.step==='1'?0:2);Q('#labWindowSub').textContent=labDraft.name};
Q('#labFields').onclick=e=>{let row=e.target.closest('[data-layer-index]'),action=e.target.closest('[data-layer-action]')?.dataset.layerAction;if(row&&!action){labLayerIndex=+row.dataset.layerIndex;renderLabFields();return}if(!action||!labDraft)return;ensureAdvancedShell(labDraft);if(['add','duplicate'].includes(action)&&labDraft.layers.length>=12){toast('A shell can contain up to twelve layers');return}if(action==='add'&&labDraft.layers.length<12){let index=labDraft.layers.length,layer=makeLabLayer(`Layer ${index+1}`,labDraft.type,labDraft.palette,{sizeScale:clamp(1-index*.16,.25,1),densityScale:.65,delay:index*.06});labDraft.layers.push(layer);labLayerIndex=labDraft.layers.length-1}else if(action==='duplicate'){let copy=structuredClone(selectedLabLayer());copy.id=uid();copy.name=copy.name+' Copy';labDraft.layers.splice(labLayerIndex+1,0,copy);labLayerIndex++}else if(action==='delete'&&labDraft.layers.length>1){let removed=labDraft.layers.splice(labLayerIndex,1)[0];if(labSoloLayerId===removed.id)labSoloLayerId=null;labLayerIndex=clamp(labLayerIndex,0,labDraft.layers.length-1)}else if(action==='up'&&labLayerIndex>0){[labDraft.layers[labLayerIndex-1],labDraft.layers[labLayerIndex]]=[labDraft.layers[labLayerIndex],labDraft.layers[labLayerIndex-1]];labLayerIndex--}else if(action==='down'&&labLayerIndex<labDraft.layers.length-1){[labDraft.layers[labLayerIndex+1],labDraft.layers[labLayerIndex]]=[labDraft.layers[labLayerIndex],labDraft.layers[labLayerIndex+1]];labLayerIndex++}else if(action==='solo'){labLayerIndex=+(e.target.dataset.layerIndex??labLayerIndex);let layer=selectedLabLayer();labSoloLayerId=labSoloLayerId===layer.id?null:layer.id}renderLabFields()};
function randomizeLab(){if(!labDraft)return;let rng=new RNG(Date.now()),aerial=SHELLS.filter(shell=>!['fountain','mine','comet-fan','roman-candle'].includes(shell.id)),type=rng.next()<.4?rng.pick(aerial).id:labDraft.type,palette=rng.pick(Object.keys(PALETTES)),previous=labDraft,definition=SHELLS.find(x=>x.id===type);labDraft=typeTune(defaultShell(type,palette));labDraft.id=previous.id;labDraft.name=`Custom ${definition.name} · ${palette}`;labDraft.family=definition?.family||'Custom';labDraft.size=rng.range(.78,1.55);labDraft.density=rng.range(.68,1.5);labDraft.spread=rng.range(.72,1.48);labDraft.chaos=rng.range(.03,.48);labDraft.glitter=rng.range(.08,.78);labDraft.crackle=rng.range(0,.58);labDraft.seed=rng.int(1,2e9);ensureAdvancedShell(labDraft);renderLabFields();labEngine.reset(labDraft.seed);labEngine.launch(labPreviewShell(),.5)}
