function slManageShape(action,index){if(!labDraft)return;const paths=labDraft.pattern.paths;if(action==='select'){if(!paths[index])return;slPath=index;slSelected.clear();slSetView('draw',false);slRenderShapes();slDrawTools();return}if(action==='rename'){if(!paths[index])return;const name=Q('[data-shape-name="'+index+'"]').value.trim().slice(0,80);if(name===paths[index].name)return;slRemember();paths[index].name=name||slShapeName({...paths[index],name:''},index);Q('[data-shape-name="'+index+'"]').value=paths[index].name;slChanged(false,false);return}if(action==='remove'&&(!Number.isInteger(index)||!paths[index]))return;if(action==='clear'&&labDraft.type==='custom'&&!paths.length)return;if(action==='duplicate'&&labDraft.type==='custom'&&!paths.length)return;const choice=action==='add'?Q('#slAddShapeKind').value:null;if(action==='add'&&labDraft.type==='custom'&&paths.length>=32){toast('A drawing supports up to 32 shapes. Remove one before adding another.');return}if(action==='duplicate'&&paths.length>=32){toast('A drawing supports up to 32 shapes.');return}slRemember();if(action==='clear'||action==='remove-base'){slUseDrawing(false);labDraft.pattern.paths=[];slPath=0}else{slUseDrawing(true);if(action==='remove'){labDraft.pattern.paths.splice(index,1);slPath=clamp(index,0,Math.max(0,labDraft.pattern.paths.length-1))}if(action==='edit-base')slPath=0;if(action==='duplicate'){const copy=structuredClone(labDraft.pattern.paths[slPath]);if(copy){copy.name=slShapeName(copy,slPath)+' copy';copy.nodes.forEach(n=>{n.x=clamp(n.x+.08,-1.5,1.5);n.y=clamp(n.y+.08,-1.5,1.5);for(const k of ['in','out'])if(n[k])n[k]=n[k].map(v=>clamp(v+.08,-2,2))});labDraft.pattern.paths.push(copy);slPath=labDraft.pattern.paths.length-1}}if(action==='add'){if(labDraft.pattern.paths.length>=32){toast('The base shell already uses 32 shapes. Remove one first.');slRefreshShapeEdit();return}slTool=choice;labDraft.pattern.mode=choice==='points'?'points':'outline';if(choice!=='freehand'){let nodes=[],closed=false;if(choice==='ellipse'){closed=true;nodes=Array.from({length:32},(_,i)=>({x:.65*Math.cos(i*Math.PI/16),y:.65*Math.sin(i*Math.PI/16)}))}if(choice==='rectangle'){closed=true;nodes=[{x:-.6,y:-.5},{x:.6,y:-.5},{x:.6,y:.5},{x:-.6,y:.5}]}if(choice==='line')nodes=[{x:-.6,y:0},{x:.6,y:0}];if(choice==='star'){closed=true;nodes=Array.from({length:labDraft.pattern.points*2},(_,i)=>{const a=i*Math.PI/labDraft.pattern.points-Math.PI/2,r=.7*(i%2?labDraft.pattern.inner:1);return{x:Math.cos(a)*r,y:Math.sin(a)*r}})}labDraft.pattern.paths.push(slNewPath(nodes,closed,choice));slPath=labDraft.pattern.paths.length-1}}}slSetView('draw',false);slRefreshShapeEdit();if(action==='add'&&['freehand','pen','points'].includes(choice))toast('Draw on the canvas to add '+({'freehand':'a freehand shape','pen':'curve points','points':'individual stars'})[choice]);else if(['remove','remove-base','clear'].includes(action))toast(action==='clear'?'All drawing shapes cleared · Undo restores them':'Shape removed · Undo restores it')}
