const slOldRender=renderLabFields;renderLabFields=function(){if(!labDraft)return;slFreshHistory();slRenderShapes();const tab=Q('.lab-tabs .active')?.dataset.labTab||'design';if(['geometry','sequence','curves','presets'].includes(tab)){Q('#labFields').innerHTML=({geometry:slGeometryFields,sequence:slSequenceFields,curves:slCurveFields,presets:slAssetFields}[tab])();if(tab==='curves')requestAnimationFrame(slDrawCurve);if(tab==='geometry')slShapeAvailability()}else{slOldRender();slPrecision();if(tab==='advanced'){const layer=selectedLabLayer();SD.defaults(layer);const body=document.createElement('div');body.className='sl-layer-extended';const inherited=['gravity','drag','windInfluence','turbulence','tilt'];for(const key of inherited)if(layer[key]==null)layer[key]=labDraft[key];body.innerHTML='<h3>THIS LAYER’S MOVEMENT</h3><div class="sl-properties">'+[['gravity','Gravity',0,2],['drag','Air drag',0,.8],['windInfluence','Wind response',0,2],['turbulence','Turbulence',0,1],['tilt','Tilt',0,1],['offsetX','Horizontal offset',-2,2],['offsetY','Vertical offset',-2,2]].map(([key,label,min,max])=>`<label class="sl-property">${label}<input data-layer-extra="${key}" type="number" min="${min}" max="${max}" step=".01" value="${layer[key]??0}"></label>`).join('')+'</div><div class="sl-row"><button data-sl="layer-shape">COPY DRAWING TO LAYER</button><button data-sl="layer-curves">COPY CHANGES TO LAYER</button><button data-sl="layer-inherit">USE MAIN SHELL MOVEMENT</button></div>';Q('.lab-layer-editor')?.append(body)}}};
