function slPreviewConfig(){const c=labPreviewShell();SD.defaults(c);return c}
function slResetSimulation(engine,config){engine.reset(config.seed);engine.cameraShake=0;engine.launch(config,.5)}
function slSyncClock(){Q('#slSeek').value=slTime;Q('#slSeek').max=slDuration;Q('#slClock').textContent=slTime.toFixed(2)+'s';Q('[data-sl="pause"]').textContent=slPaused?'Resume':'Pause';for(const action of ['step','rewind'])Q('[data-sl="'+action+'"]').disabled=slView==='draw';Q('#slSeek').disabled=slView==='draw';Q('#slPreviewStatus').textContent=slView==='draw'?'Drawing · Preview plays this design':slPreviewDirty?'Updating preview…':`${slPaused?'Paused':'Playing'} · ${labEngine?.particles.length||0} stars · seed ${labDraft?.seed||0}`}

function slPaint(){if(!labEngine)return;labEngine.render();if(slView==='compare'){for(const [engine,id] of [[slReferenceEngine,'slCompareA'],[labEngine,'slCompareB']]){const cv=Q('#'+id),r=cv.getBoundingClientRect();cv.width=Math.max(1,r.width*devicePixelRatio);cv.height=Math.max(1,r.height*devicePixelRatio);const ctx=cv.getContext('2d');ctx.fillStyle='#02050b';ctx.fillRect(0,0,cv.width,cv.height);if(engine){const scale=Math.min(cv.width/engine.canvas.width,cv.height/engine.canvas.height),w=engine.canvas.width*scale,h=engine.canvas.height*scale;ctx.drawImage(engine.canvas,(cv.width-w)/2,(cv.height-h)/2,w,h)}}}slSyncClock()}
async function slSeek(seconds,pause=true){if(!labDraft||!labEngine)return;const token=++slSeekToken;slSeeking=true;if(pause)slPaused=true;try{const c=slPreviewConfig();slDuration=Math.min(30,Math.max(12,c.lifetime+8,...c.sequence.stages.map(s=>(+s.time||0)+c.lifetime*(+s.life||1)+5)));const target=clamp(Math.round(seconds*60)/60,0,slDuration);labEngine.sound.setEnabled(false);slSizePreview();slResetSimulation(labEngine,c);if(slView==='compare'&&slReference){if(!slReferenceEngine)slReferenceEngine=new FireworkEngine(document.createElement('canvas'));slReferenceEngine.setQuality('high');slReferenceEngine.w=labEngine.w;slReferenceEngine.h=labEngine.h;slReferenceEngine.scale=labEngine.scale;slReferenceEngine.canvas.width=labEngine.canvas.width;slReferenceEngine.canvas.height=labEngine.canvas.height;slReferenceEngine.sound.setEnabled(false);slResetSimulation(slReferenceEngine,slReference)}const frames=Math.round(target*60);for(let frame=0;frame<frames;frame++){if(token!==slSeekToken)return false;labEngine.update(1/60);if(slView==='compare'&&slReferenceEngine)slReferenceEngine.update(1/60);if(frame%120===119)await new Promise(requestAnimationFrame)}if(token!==slSeekToken)return false;labEngine.sound.setEnabled(state.show.sfxEnabled!==false);slSeeking=false;slPreviewDirty=false;slAccumulator=0;slTime=target;if(slReferenceEngine)slReferenceEngine.render();slPaint();return true}catch(error){if(token===slSeekToken){slPaused=true;toast('Preview could not update: '+error.message)}return false}finally{if(token===slSeekToken){slSeeking=false;labEngine.sound.setEnabled(state.show.sfxEnabled!==false)}}}
let slLastFrame=performance.now(),slAccumulator=0,slSeeking=false;
labLoop=function(now){const dt=Math.min(.08,(now-slLastFrame)/1000);slLastFrame=now;if(labEngine&&!slPanel.hidden&&!slSeeking){if(slView==='draw'){/* Drawing redraws on edits and resize, not every animation frame. */}else if(!slPaused){slAccumulator+=dt*slSpeed;let steps=0;while(slAccumulator>=1/60&&steps++<5){labEngine.update(1/60);if(slView==='compare'&&slReferenceEngine)slReferenceEngine.update(1/60);slAccumulator-=1/60;slTime+=1/60}if(slTime>=slDuration){slPaused=true}if(slReferenceEngine)slReferenceEngine.render();slPaint()}else slPaint()}labFrame=requestAnimationFrame(labLoop)};
const slOldOpen=openShellLab;openShellLab=function(...args){slCancelPreview();cancelAnimationFrame(slOpenFrame);slOldOpen(...args);SD.relaxLegacyPreset(labDraft);slFreshHistory();slSelected.clear();slPath=0;slTime=0;slSetView(slView,false);slOpenFrame=requestAnimationFrame(()=>{if(slPanel.hidden)return;slStartPreview()})};
const slOldRandom=randomizeLab;randomizeLab=function(){slRemember();const previous=structuredClone(labDraft);slOldRandom();if(slLock.shape){for(const k of ['type','family','pattern','layers','layered','sequence','branching','rotation','tilt','spread','size','density'])if(previous[k]!=null)labDraft[k]=structuredClone(previous[k])}if(slLock.colors)for(const k of ['palette','colors','colorProgram'])if(previous[k]!=null)labDraft[k]=structuredClone(previous[k]);if(slLock.physics)for(const k of ['gravity','drag','windInfluence','turbulence','particleSpeed','speedVariance','lifetime','lifetimeVariance','curves','launchHeight','launchSpeed','launchAngle','launchWobble'])if(previous[k]!=null)labDraft[k]=structuredClone(previous[k]);if(slLock.seed)labDraft.seed=previous.seed;slChanged();renderLabFields();slSeek(0,false);slPaused=false};
const slOldResetDefaults=resetLabDefaults;resetLabDefaults=function(){slRemember();slOldResetDefaults();slChanged();slSeek(0,false);slPaused=false};
function slSetView(view,rebuild=true){if(view==='compare'&&!slReference){toast('Save a reference first, then compare your changes.');return false}slView=view;Q('#labCanvas').classList.toggle('sl-hidden',view!=='live');slDraw.classList.toggle('sl-hidden',view!=='draw');slToolsCard.classList.toggle('sl-hidden',view!=='draw');slCompare.classList.toggle('sl-hidden',view!=='compare');QA('[data-sl-view]').forEach(b=>b.classList.toggle('active',b.dataset.slView===view));if(view==='draw'){++slSeekToken;slSeeking=false;slPaused=true;labEngine?.sound.setEnabled(state.show.sfxEnabled!==false);slDrawTools();requestAnimationFrame(slDrawShape);slSyncClock()}else if(rebuild&&labEngine){clearTimeout(slPreviewTimer);slSeek(slTime>.5&&slTime<slDuration-.25?slTime:2.5)}return true}
async function slStartPreview(){if(!labDraft||!labEngine)return;if(labDraft.type==='custom'&&!labDraft.pattern.paths.some(path=>path.nodes.length)&&!labDraft.layered&&!labDraft.sequence.enabled){slPaused=true;labEngine.reset(labDraft.seed);slPaint();toast('Add a shape before previewing this drawing.');return}clearTimeout(slPreviewTimer);slPaused=true;slSetView(slView==='compare'?'compare':'live',false);const completed=await slSeek(0,false);if(completed&&!slPanel.hidden){slPaused=false;slLastFrame=performance.now();slPaint()}}
function slTogglePause(){if(slView==='draw'||slTime>=slDuration){slStartPreview();return}slPaused=!slPaused;slLastFrame=performance.now();slSyncClock()}
