Q('#slDrawing').onpointermove=e=>{if(!slDrag||!labDraft)return;const p=slPos(e,slDrag.kind!=='freehand'),d=slDrag;if(['move','handle'].includes(d.kind)&&!d.remembered&&Math.hypot(p.x-d.start.x,p.y-d.start.y)>.001){slRemember();d.remembered=true}if(d.kind==='box')d.end=p;if(d.kind==='move'){const dx=p.x-d.start.x,dy=p.y-d.start.y;for(const key of slSelected){const [pi,i]=key.split(':').map(Number),n=labDraft.pattern.paths[pi]?.nodes[i],o=d.original[pi]?.nodes[i];if(!n||!o)continue;n.x=clamp(o.x+dx,-1.5,1.5);n.y=clamp(o.y+dy,-1.5,1.5);for(const k of ['in','out'])if(o[k])n[k]=[o[k][0]+dx,o[k][1]+dy]}}if(d.kind==='handle'){const n=labDraft.pattern.paths[d.hit.pi].nodes[d.hit.i];n[d.hit.key]=[p.x,p.y];if(e.shiftKey){const other=d.hit.key==='in'?'out':'in';n[other]=[n.x*2-p.x,n.y*2-p.y]}}if(d.kind==='curve'){const n=slEnsurePath().nodes[d.index];n.out=[p.x,p.y];n.in=[n.x*2-p.x,n.y*2-p.y]}if(d.kind==='freehand'){const path=slEnsurePath(),last=path.nodes.at(-1);if(path.nodes.length<512&&Math.hypot(last.x-p.x,last.y-p.y)>.025)path.nodes.push(p)}if(d.kind==='primitive'){const a=d.start,path=slEnsurePath(),cx=(a.x+p.x)/2,cy=(a.y+p.y)/2,rx=Math.abs(p.x-a.x)/2,ry=Math.abs(p.y-a.y)/2;if(d.tool==='line')path.nodes=[a,p];if(d.tool==='rectangle')path.nodes=[a,{x:p.x,y:a.y},p,{x:a.x,y:p.y}];if(d.tool==='ellipse')path.nodes=Array.from({length:32},(_,i)=>({x:cx+rx*Math.cos(i*Math.PI/16),y:cy+ry*Math.sin(i*Math.PI/16)}));if(d.tool==='star')path.nodes=Array.from({length:labDraft.pattern.points*2},(_,i)=>{const q=i*Math.PI/labDraft.pattern.points,r=i%2?labDraft.pattern.inner:1;return{x:cx+rx*Math.cos(q)*r,y:cy+ry*Math.sin(q)*r}})}slDrawShape()};
Q('#slDrawing').onpointerup=e=>{if(!slDrag)return;if(slDrag.kind==='box'){const a=slDrag.start,b=slDrag.end;labDraft.pattern.paths.forEach((p,pi)=>p.nodes.forEach((n,i)=>{if(n.x>=Math.min(a.x,b.x)&&n.x<=Math.max(a.x,b.x)&&n.y>=Math.min(a.y,b.y)&&n.y<=Math.max(a.y,b.y))slSelected.add(pi+':'+i)}))}if(slDrag.kind==='freehand'&&labDraft.pattern.autoSmooth!==false&&labDraft.pattern.mode!=='points'){labDraft.pattern.paths[slPath]=SD.correctPath(slEnsurePath(),{strength:labDraft.pattern.smoothness})}const edited=!['box','move','handle'].includes(slDrag.kind)||slDrag.remembered;slDrag=null;if(edited)slChanged();slDrawTools();slRenderShapes();slDrawShape()};Q('#slDrawing').onpointercancel=()=>{if(!slDrag)return;slDrag=null;slChanged();slDrawTools();slDrawShape()};
